namespace DMO.Alpha.Core.Admin;

/// <summary>
/// The provisioning seam of the Admin → Users workflows (USERS.md §2/§5):
/// DMO ASKS the Auth provider (Supabase Auth) to create — or re-establish
/// the credential of — an authentication identity, and NEVER becomes a
/// password store itself (USERS.md §2: "DMO does not become a password
/// store"). The temporary password is a bootstrap/reset credential only:
/// it is generated by DMO, handed to the ADMIN once (who hands it to the
/// User), and the User's own permanent password is chosen through the
/// provider on the forced change after login — DMO never sees or stores
/// it. The login surface itself is a pass-through of the provider (the
/// sign-in path resolves identities by the provider's own user id).
/// </summary>
public interface IUserProvisioningProvider
{
    /// <summary>
    /// Provisions a NEW authentication identity with the given email and
    /// temporary bootstrap password. The identity is born confirmed for
    /// login and flagged as requiring the User's own private password
    /// choice on first use. An email already known to the provider is a
    /// typed refusal (EmailExists) — never a silent duplicate.
    /// </summary>
    Task<UserProvisioningCreateResult> CreateAsync(
        string email,
        string temporaryPassword,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Re-establishes the credential of an EXISTING provider identity
    /// (the ADMIN reset flow, USERS.md §5): a new temporary password
    /// replaces the previous credential, and the forced private-password
    /// change is re-armed for the next login. The identity that does not
    /// exist on the provider side is a typed refusal.
    /// </summary>
    Task<UserProvisioningResetResult> ResetAsync(
        string providerUserId,
        string temporaryPassword,
        CancellationToken cancellationToken = default);

    Task<UserProvisioningDeleteResult> DeleteAsync(string providerUserId, CancellationToken cancellationToken = default);
}

public enum UserProvisioningDeleteStatus { Success, IdentityNotFound, ProviderFailure }

public sealed record UserProvisioningDeleteResult(UserProvisioningDeleteStatus Status)
{
    public static UserProvisioningDeleteResult Success() => new(UserProvisioningDeleteStatus.Success);
    public static UserProvisioningDeleteResult IdentityNotFound() => new(UserProvisioningDeleteStatus.IdentityNotFound);
    public static UserProvisioningDeleteResult ProviderFailure() => new(UserProvisioningDeleteStatus.ProviderFailure);
}

/// <summary>
/// Resultado tipado do provisionamento de uma identidade nova. Vocabulário
/// FECHADO (USERS.md §2): o email duplicado é recusa tipada — a criação do
/// User correspondente nunca acontece por cima de uma identidade ambígua.
/// </summary>
public sealed record UserProvisioningCreateResult
{
    public required UserProvisioningCreateStatus Status { get; init; }

    /// <summary>The provider-owned identity of the created account (Success only).</summary>
    public string? ProviderUserId { get; init; }

    public static UserProvisioningCreateResult Success(string providerUserId) =>
        new() { Status = UserProvisioningCreateStatus.Success, ProviderUserId = providerUserId };

    public static UserProvisioningCreateResult EmailExists() =>
        new() { Status = UserProvisioningCreateStatus.EmailExists };

    public static UserProvisioningCreateResult ProviderFailure() =>
        new() { Status = UserProvisioningCreateStatus.ProviderFailure };
}

public enum UserProvisioningCreateStatus
{
    /// <summary>Identity created; <c>ProviderUserId</c> carries the new identity.</summary>
    Success,

    /// <summary>The email is already a provider identity — typed duplicate refusal.</summary>
    EmailExists,

    /// <summary>The provider refused or failed — no identity was created.</summary>
    ProviderFailure
}

/// <summary>
/// Resultado tipado do reset de acesso (USERS.md §5). Vocabulário FECHADO.
/// </summary>
public sealed record UserProvisioningResetResult
{
    public required UserProvisioningResetStatus Status { get; init; }

    public static UserProvisioningResetResult Success() =>
        new() { Status = UserProvisioningResetStatus.Success };

    public static UserProvisioningResetResult IdentityNotFound() =>
        new() { Status = UserProvisioningResetStatus.IdentityNotFound };

    public static UserProvisioningResetResult ProviderFailure() =>
        new() { Status = UserProvisioningResetStatus.ProviderFailure };
}

public enum UserProvisioningResetStatus
{
    /// <summary>New temporary credential established; forced private change re-armed.</summary>
    Success,

    /// <summary>No such provider identity — typed refusal.</summary>
    IdentityNotFound,

    /// <summary>The provider refused or failed — the previous credential stays untouched.</summary>
    ProviderFailure
}
